  const cy0 = -hHeight / 2 + padding + r;
  const colors: SignalColor[] = ['RED', 'YELLOW', 'GREEN'];
  colors.forEach((c, i) => {
    const yy = cy0 + i * (r * 2 + padding);
    ctx.beginPath();
    ctx.arc(0, yy, r, 0, Math.PI * 2);
    ctx.fillStyle = color === c ? COLORS.light[c] : COLORS.light.OFF;
    ctx.fill();
    ctx.strokeStyle = COLORS.signalRing;
    ctx.lineWidth = 1;
    ctx.stroke();
    if (color === c) {
      // soft glow
      ctx.beginPath();
      ctx.arc(0, yy, r + 2, 0, Math.PI * 2);
      ctx.strokeStyle = withAlpha(COLORS.light[c], 0.35);
      ctx.lineWidth = 2;
      ctx.stroke();
    }
  });
  ctx.restore();
}

function drawLeftSignalHead(
  ctx: CanvasRenderingContext2D,
  approach: Approach,
  color: LeftSignalColor,
): void {
  const pos = signalHeadPosition(approach, 'LEFT');
  const r = 5;
  const padding = 3;
  const hWidth = r * 2 + padding * 2;
  const hHeight = r * 8 + padding * 5;
  ctx.save();
  ctx.translate(pos.x, pos.y);
  ctx.fillStyle = COLORS.signalHousing;
  roundRect(ctx, -hWidth / 2, -hHeight / 2, hWidth, hHeight, 3);
  ctx.fill();
  const cy0 = -hHeight / 2 + padding + r;
  const colors: LeftSignalColor[] = ['RED', 'YELLOW', 'FLASHING_ORANGE', 'GREEN'];
  colors.forEach((c, i) => {
    const yy = cy0 + i * (r * 2 + padding);
    const lit = color === c;
    ctx.beginPath();
    ctx.arc(0, yy, r, 0, Math.PI * 2);
    ctx.fillStyle = lit ? COLORS.light[c] : COLORS.light.OFF;
    ctx.fill();
    ctx.strokeStyle = COLORS.signalRing;
    ctx.lineWidth = 1;
    ctx.stroke();
    // Draw an arrow glyph on the LEFT signal so it's distinguishable from a through head.
    if (i === 3) {
      // bottom = green; nothing extra to draw since arrow shape is implied
    }
    if (lit) {
      ctx.beginPath();
      ctx.arc(0, yy, r + 2, 0, Math.PI * 2);
      ctx.strokeStyle = withAlpha(COLORS.light[c], 0.35);
      ctx.lineWidth = 2;
      ctx.stroke();
    }
  });
  // Small "L" badge at top to identify left-turn signal.
  ctx.fillStyle = '#7d8896';
  ctx.font = '9px monospace';
  ctx.textAlign = 'center';
  ctx.fillText('L', 0, -hHeight / 2 - 3);
  ctx.restore();
}

function withAlpha(hex: string, alpha: number): string {
  // Accepts #rrggbb only.
  const r = parseInt(hex.slice(1, 3), 16);
  const g = parseInt(hex.slice(3, 5), 16);
  const b = parseInt(hex.slice(5, 7), 16);
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

