/** Position of the i-th queued car (i=0 closest to stop line) in lane (approach, kind). */
export function queuedCarPosition(approach: Approach, kind: LaneKind, i: number): Vec {
  return queuedCarPositionInSubLane(approach, kind, 0, i);
}

/**
 * Position of a queued car in a specific sub-lane.
 * `stackIndex` = 0 means at the stop line; higher = farther back.
 */
export function queuedCarPositionInSubLane(
  approach: Approach,
  kind: LaneKind,
  subLaneIndex: number,
  stackIndex: number,
): Vec {
  const center = subLaneCenterAtStopLine(approach, kind, subLaneIndex);
  const travel = TRAVEL_DIRS[approach];
  const dist = CAR_LENGTH / 2 + 4 + stackIndex * (CAR_LENGTH + CAR_GAP);
  return {
    x: center.x - travel.x * dist,
    y: center.y - travel.y * dist,
  };
}

// ── Path geometry for cars traversing the intersection ──────────────────────

/** Quadratic-Bezier path: entry → control → exit. Same shape used for all moves. */
export interface CarPath {
  entry: Vec;
  control: Vec;
  exit: Vec;
}

export function pathFor(approach: Approach, kind: LaneKind, subLaneIndex: number): CarPath {
  const entry = subLaneCenterAtStopLine(approach, kind, subLaneIndex);
  const exit = exitPointFor(approach, kind);
  const control = controlPointFor(approach, kind, entry, exit);
  return { entry, control, exit };
}

/**
 * Exit point in canvas coordinates, just past the far edge of the intersection.
 *   STRAIGHT  → continue in same direction
 *   LEFT      → exit on perpendicular side (CCW rotation of travel)
 *   RIGHT     → exit on perpendicular side (CW rotation of travel)
 */
function exitPointFor(approach: Approach, kind: LaneKind): Vec {
  const t = TRAVEL_DIRS[approach];
  const beyond = HALF_INTERSECTION + 30;

  if (kind === 'STRAIGHT') {
    // Continue past the opposite stop line on the same lateral offset (same x for N/S, same y for E/W).
    const entry = subLaneCenterAtStopLine(approach, kind, 0);
    return { x: entry.x + t.x * (HALF_INTERSECTION * 2 + 30), y: entry.y + t.y * (HALF_INTERSECTION * 2 + 30) };
  }

  // For turns, derive the post-turn travel direction.
  // LEFT  in canvas (y-down): rotate CCW = (y, -x)... but in y-down, "visual CCW" is math CW.
  //   For N (travel south = (0,1)): left turn → east = (1,0).
  //     CCW math: (0,1) → (1,0)  ✓
  //   For E (travel west = (-1,0)): left turn → south = (0,1).
  //     CCW math: (-1,0) → (0,-1)  ✗  (math CCW gives (0,-1) which is north, wrong for canvas y-down)
  //   So in canvas y-down, "physical left turn" = math CW = (y, -x)? No:
  //     For N: (0,1) → physical-left=east=(1,0). y-down CW: (x,y)→(-y,x) → (-1, 0) wrong. CCW: (y,-x) → (1,0) ✓.
  //     For E: (-1,0) → physical-left=south=(0,1). y-down CCW: (y,-x) → (0,1) ✓.
  //   So LEFT = (y, -x). RIGHT = (-y, x).
  const turnDir =
    kind === 'LEFT'
      ? { x: t.y, y: -t.x }
      : { x: -t.y, y: t.x };
  return { x: CENTER + turnDir.x * beyond, y: CENTER + turnDir.y * beyond };
}

/** Control point for the quadratic bezier. For STRAIGHT, midpoint (linear). For turns, the corner. */
function controlPointFor(approach: Approach, kind: LaneKind, entry: Vec, exit: Vec): Vec {
  if (kind === 'STRAIGHT') {
    return { x: (entry.x + exit.x) / 2, y: (entry.y + exit.y) / 2 };
  }
  // Turns: control point is at the "corner" — entry's lateral coord, exit's longitudinal coord.
  if (approach === 'N' || approach === 'S') {
    // Entry varies in x along stop line; exit varies in y. Corner at (entry.x, exit.y).
    return { x: entry.x, y: exit.y };
  }
  return { x: exit.x, y: entry.y };
}

export function bezierPos(p: CarPath, t: number): Vec {
  const u = 1 - t;
  return {
    x: u * u * p.entry.x + 2 * u * t * p.control.x + t * t * p.exit.x,
    y: u * u * p.entry.y + 2 * u * t * p.control.y + t * t * p.exit.y,
  };
}

export function bezierTangent(p: CarPath, t: number): Vec {
  const u = 1 - t;
  return {
    x: 2 * u * (p.control.x - p.entry.x) + 2 * t * (p.exit.x - p.control.x),
    y: 2 * u * (p.control.y - p.entry.y) + 2 * t * (p.exit.y - p.control.y),
  };
}

