/**
 * Signal heads sit just outside the intersection box on the curb side
 * relative to each approach. Through+right share one head; LEFT has its own.
 */
export function signalHeadPosition(approach: Approach, kind: LaneKind): Vec {
  // Distance from intersection edge to signal head (along travel direction, outward).
  const along = -28; // outside the intersection box (opposite to travelDir)
  // Lateral offset from the centerline for the signal head:
  //   - through/right head sits on the curb side of the through lanes
  //   - LEFT head sits inboard (close to centerline)
  const lateral = kind === 'LEFT' ? LANE_WIDTH * 0.5 : LANE_WIDTH * 3.0;
  const travel = TRAVEL_DIRS[approach];

  // perpendicular = rotate travel 90° clockwise (in canvas y-down: rot CW = (-y, x))
  const perp = { x: -travel.y, y: travel.x };

  // For each approach, "curb side" means the side of the road the right lane is on.
  // For N (south travel), right lane is on the WEST → perp from (0,1) CW is (-1,0). Good.
  // For S (north travel), right lane is EAST → perp from (0,-1) CW is (1,0). Good.
  // For E (west travel), right lane is NORTH → perp from (-1,0) CW is (0,-1). Good.
  // For W (east travel), right lane is SOUTH → perp from (1,0) CW is (0,1). Good.

  // Start from intersection edge midpoint along this approach's stop line, then offset.
  const stopMid = stopLineMidpoint(approach);
  return {
    x: stopMid.x + travel.x * along + perp.x * lateral,
    y: stopMid.y + travel.y * along + perp.y * lateral,
  };
}

function stopLineMidpoint(approach: Approach): Vec {
  switch (approach) {
    case 'N': return { x: CENTER - HALF_ROAD / 2, y: STOP_LINES.N };
    case 'S': return { x: CENTER + HALF_ROAD / 2, y: STOP_LINES.S };
    case 'E': return { x: STOP_LINES.E, y: CENTER - HALF_ROAD / 2 };
    case 'W': return { x: STOP_LINES.W, y: CENTER + HALF_ROAD / 2 };
  }
}

input.new_string:
/**
 * Signal head placement uses the **far-side overhead-gantry** convention:
 * each signal sits just past the *opposite* stop line, centered over the lane
 * group it controls. From the driver's POV approaching from N, the signals
 * appear hanging at the far end of the intersection, directly above the
 * lanes they control. This is how real intersections are signed.
 *
 * Two heads per approach:
 *   - through+right (3-aspect: R/Y/G) — centered over its three lanes
 *   - LEFT          (4-aspect: R/Y/flashing-orange/G) — centered over the LEFT lane
 */
export function signalHeadPosition(approach: Approach, kind: LaneKind): Vec {
  const past = 28; // distance past the far stop line where the gantry sits

  // For STRAIGHT (which doubles as through+right), center the head over the
  // average of the three controlled lanes (idx 1, 2, 3 from the centerline).
  // For LEFT, center over the LEFT lane (idx 0).
  const centerOffsetFromCenterline =
    kind === 'LEFT'
      ? (0 + 0.5) * LANE_WIDTH         // 12.5 — LEFT lane center
      : ((1 + 2 + 3) / 3 + 0.5) * LANE_WIDTH; // 62.5 — center of three through+right lanes

  switch (approach) {
    // N approach traffic (southbound): controlled lanes are on the west half.
    // Signal sits past STOP_LINES.S, lateral position west of centerline.
    case 'N': return { x: CENTER - centerOffsetFromCenterline, y: STOP_LINES.S + past };
    // S approach traffic (northbound): east half. Signal past STOP_LINES.N.
    case 'S': return { x: CENTER + centerOffsetFromCenterline, y: STOP_LINES.N - past };
    // E approach traffic (westbound): north half. Signal past STOP_LINES.W.
    case 'E': return { x: STOP_LINES.W - past, y: CENTER - centerOffsetFromCenterline };
    // W approach traffic (eastbound): south half. Signal past STOP_LINES.E.
    case 'W': return { x: STOP_LINES.E + past, y: CENTER + centerOffsetFromCenterline };
  }
}

/**
 * Rotation of the signal housing so its long axis lies *across* the road
 * (perpendicular to the approach direction). This matches how an overhead
 * gantry is mounted in real life — the bar spans the lanes.
 *
 *   N/S approaches → housing horizontal (long axis east–west, rotation = π/2)
 *   E/W approaches → housing vertical   (long axis north–south, rotation = 0)
 */
export function signalHousingRotation(approach: Approach): number {
  return approach === 'N' || approach === 'S' ? Math.PI / 2 : 0;
}

