/**
 * Signal head placement uses the **far-side overhead-gantry** convention:
 * each signal sits just past the *opposite* stop line, centered over the lane
 * group it controls. From the driver's POV approaching from N, the signals
 * appear hanging at the far end of the intersection, directly above the
 * lanes they control. This is how real intersections are signed.
 *
 * Two heads per approach:
 *   - through+right (3-aspect: R/Y/G) — centered over its three lanes
 *   - LEFT          (4-aspect: R/Y/flashing-orange/G) — centered over the LEFT lane
 */
export function signalHeadPosition(approach: Approach, kind: LaneKind): Vec {
  const past = 28; // distance past the far stop line where the gantry sits

  // For STRAIGHT (which doubles as through+right), center the head over the
  // average of the three controlled lanes (idx 1, 2, 3 from the centerline).
  // For LEFT, center over the LEFT lane (idx 0).
  const centerOffsetFromCenterline =
    kind === 'LEFT'
      ? (0 + 0.5) * LANE_WIDTH         // 12.5 — LEFT lane center
      : ((1 + 2 + 3) / 3 + 0.5) * LANE_WIDTH; // 62.5 — center of three through+right lanes

  switch (approach) {
    // N approach traffic (southbound): controlled lanes are on the west half.
    // Signal sits past STOP_LINES.S, lateral position west of centerline.
    case 'N': return { x: CENTER - centerOffsetFromCenterline, y: STOP_LINES.S + past };
    // S approach traffic (northbound): east half. Signal past STOP_LINES.N.
    case 'S': return { x: CENTER + centerOffsetFromCenterline, y: STOP_LINES.N - past };
    // E approach traffic (westbound): north half. Signal past STOP_LINES.W.
    case 'E': return { x: STOP_LINES.W - past, y: CENTER - centerOffsetFromCenterline };
    // W approach traffic (eastbound): south half. Signal past STOP_LINES.E.
    case 'W': return { x: STOP_LINES.E + past, y: CENTER + centerOffsetFromCenterline };
  }
}

