/**
 * Signal head placement.
 *
 * Two heads per approach, both rendered as vertical 3-/4-light housings (the
 * universally recognizable stoplight form):
 *
 *   - Through+right head — at the **far-right corner** from the driver's POV,
 *     just outside the intersection box. This is where an overhead-gantry
 *     pole stands in a real US intersection. The driver looks slightly down
 *     and to their right (relative to travel direction) to see it.
 *
 *   - LEFT-turn head — directly over the LEFT lane on the far side, just past
 *     the far stop line. Same as a real protected-left signal hanging off the
 *     gantry arm above the LEFT lane.
 *
 * "Far-right corner" by approach (driver looks toward this corner ahead):
 *   N → SW corner   (driver going south, right=west, far=south)
 *   S → NE corner
 *   E → NW corner
 *   W → SE corner
 */
const FAR_PAST = 26;       // distance past the far stop line
const CORNER_INSET = 14;   // how far outside the corner of the intersection box

export function signalHeadPosition(approach: Approach, kind: LaneKind): Vec {
  if (kind === 'LEFT') {
    // Center over the LEFT lane (idx 0 from the centerline).
    const offset = 0.5 * LANE_WIDTH;
    switch (approach) {
      case 'N': return { x: CENTER - offset, y: STOP_LINES.S + FAR_PAST };
      case 'S': return { x: CENTER + offset, y: STOP_LINES.N - FAR_PAST };
      case 'E': return { x: STOP_LINES.W - FAR_PAST, y: CENTER - offset };
      case 'W': return { x: STOP_LINES.E + FAR_PAST, y: CENTER + offset };
    }
  }
  // Through+right head: at the far-right corner from driver POV.
  switch (approach) {
    case 'N': return { x: STOP_LINES.W - CORNER_INSET, y: STOP_LINES.S + CORNER_INSET };
    case 'S': return { x: STOP_LINES.E + CORNER_INSET, y: STOP_LINES.N - CORNER_INSET };
    case 'E': return { x: STOP_LINES.W - CORNER_INSET, y: STOP_LINES.N - CORNER_INSET };
    case 'W': return { x: STOP_LINES.E + CORNER_INSET, y: STOP_LINES.S + CORNER_INSET };
  }
}

/** All signal housings render upright (no rotation) — the recognizable stoplight form. */
export function signalHousingRotation(_approach: Approach): number {
  return 0;
}

