      base:    { x: STOP_LINES.E + CORNER_OUT, y: STOP_LINES.N - CORNER_OUT },
      inboard: { x: -1, y: 0 },
      poleAt:  { x: STOP_LINES.E,             y: STOP_LINES.N             },
