input.old_string:
/**
 * Draw the corner pole and the horizontal arm that the two signal heads
 * "hang from". Purely decorative — makes the pair read as one mounted
 * fixture instead of two unrelated signals at random points in space.
 */
function drawSignalGantry(ctx: CanvasRenderingContext2D, approach: Approach): void {
  const pole = signalPolePosition(approach);
  const through = signalHeadPosition(approach, 'STRAIGHT');
  const left = signalHeadPosition(approach, 'LEFT');

  ctx.save();
  ctx.strokeStyle = '#3a4250';
  ctx.lineWidth = 2;
  ctx.lineCap = 'round';

  // Short stub from the corner pole to the through head's anchor.
  ctx.beginPath();
  ctx.moveTo(pole.x, pole.y);
  ctx.lineTo(through.x, through.y);
  ctx.stroke();

  // Arm extending from the through head to the LEFT head.
  ctx.beginPath();
  ctx.moveTo(through.x, through.y);
  ctx.lineTo(left.x, left.y);
  ctx.stroke();

  // Small disc at the corner — the pole base.
  ctx.fillStyle = '#0a0d11';
  ctx.beginPath();
  ctx.arc(pole.x, pole.y, 3.5, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = '#3a4250';
  ctx.lineWidth = 1;
  ctx.stroke();

  ctx.restore();
}

input.new_string:
/**
 * Draw the gantry: pole at the corner, vertical stub down/up to the fixture
 * row, and a horizontal arm extending across both signal heads. The signal
 * head closer to the pole "hangs from" the arm en route to the far one.
 */
function drawSignalGantry(ctx: CanvasRenderingContext2D, approach: Approach): void {
  const pole = signalPolePosition(approach);
  const through = signalHeadPosition(approach, 'STRAIGHT');
  const left = signalHeadPosition(approach, 'LEFT');
  const fixtureY = through.y; // both heads share the same y
  // Reach the arm out to whichever head is farther from the corner pole.
  const farX = Math.abs(through.x - pole.x) > Math.abs(left.x - pole.x) ? through.x : left.x;

  ctx.save();
  ctx.strokeStyle = '#3a4250';
  ctx.lineWidth = 2;
  ctx.lineCap = 'round';

  // Vertical segment from corner pole down/up to the gantry arm row.
  ctx.beginPath();
  ctx.moveTo(pole.x, pole.y);
  ctx.lineTo(pole.x, fixtureY);
  ctx.stroke();

  // Horizontal arm out to the far head.
  ctx.beginPath();
  ctx.moveTo(pole.x, fixtureY);
  ctx.lineTo(farX, fixtureY);
  ctx.stroke();

  // Pole base disc at the corner.
  ctx.fillStyle = '#0a0d11';
  ctx.beginPath();
  ctx.arc(pole.x, pole.y, 3.5, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = '#3a4250';
  ctx.lineWidth = 1;
  ctx.stroke();

  ctx.restore();
}

