input.new_string:
/**
 * Signal head placement — one fixture per approach, **with each head
 * centered over the lanes it controls**. Each approach's pair sits on a
 * gantry arm extending from a pole at the corresponding intersection
 * corner; the arm runs perpendicular to the road so each signal head
 * hangs directly above its lane group. This is how real overhead-gantry
 * intersections are signed — and it makes the lane→signal association
 * obvious at a glance.
 *
 *   - LEFT head:    centered over the LEFT lane (idx 0 from centerline)
 *   - through head: centered over the three through+right lanes (idx 1–3,
 *                   so its center sits at idx 2 = LANE_WIDTH * 2.5 out
 *                   from the centerline)
 *
 * Pole anchors at the corner of the intersection on the curb side of the
 * approach (driver's right when entering).
 */
const FAR_PAST = 30;                              // distance past the far stop line
const LEFT_LANE_OFFSET = 0.5 * LANE_WIDTH;        // center of the LEFT lane from the centerline
const THROUGH_GROUP_OFFSET = 2.5 * LANE_WIDTH;    // center of the three through+right lanes

interface FixtureLayout {
  leftPos: Vec;     // 4-aspect LEFT head — over the LEFT lane
  throughPos: Vec;  // 3-aspect through head — over the through+right lane group
  poleAt: Vec;      // intersection corner the gantry pole anchors at
}

function fixtureLayout(approach: Approach): FixtureLayout {
  switch (approach) {
    case 'N': {
      // Lanes are on the west half. Signals south of intersection.
      const y = STOP_LINES.S + FAR_PAST;
      return {
        leftPos:    { x: CENTER - LEFT_LANE_OFFSET,    y },
        throughPos: { x: CENTER - THROUGH_GROUP_OFFSET, y },
        poleAt:     { x: STOP_LINES.W, y: STOP_LINES.S }, // SW corner
      };
    }
    case 'S': {
      // Lanes on east half. Signals north of intersection.
      const y = STOP_LINES.N - FAR_PAST;
      return {
        leftPos:    { x: CENTER + LEFT_LANE_OFFSET,    y },
        throughPos: { x: CENTER + THROUGH_GROUP_OFFSET, y },
        poleAt:     { x: STOP_LINES.E, y: STOP_LINES.N }, // NE corner
      };
    }
    case 'E': {
      // Lanes on north half. Signals west of intersection.
      const x = STOP_LINES.W - FAR_PAST;
      return {
        leftPos:    { x, y: CENTER - LEFT_LANE_OFFSET },
        throughPos: { x, y: CENTER - THROUGH_GROUP_OFFSET },
        poleAt:     { x: STOP_LINES.W, y: STOP_LINES.N }, // NW corner
      };
    }
    case 'W': {
      // Lanes on south half. Signals east of intersection.
      const x = STOP_LINES.E + FAR_PAST;
      return {
        leftPos:    { x, y: CENTER + LEFT_LANE_OFFSET },
        throughPos: { x, y: CENTER + THROUGH_GROUP_OFFSET },
        poleAt:     { x: STOP_LINES.E, y: STOP_LINES.S }, // SE corner
      };
    }
  }
}

