function drawSignalHead(
  ctx: CanvasRenderingContext2D,
  approach: Approach,
  kind: LaneKind,
  color: SignalColor,
): void {
  const pos = signalHeadPosition(approach, kind);
  const rot = signalHousingRotation(approach);
  const r = 5;
  const padding = 3;
  // Three-light vertical housing — universally recognizable stoplight form.
  const hWidth = r * 2 + padding * 2;
  const hHeight = r * 6 + padding * 4;
  ctx.save();
  ctx.translate(pos.x, pos.y);
  ctx.rotate(rot);
  ctx.fillStyle = COLORS.signalHousing;
  roundRect(ctx, -hWidth / 2, -hHeight / 2, hWidth, hHeight, 4);
  ctx.fill();
  const cy0 = -hHeight / 2 + padding + r;
  const colors: SignalColor[] = ['RED', 'YELLOW', 'GREEN'];
  colors.forEach((c, i) => {
    const yy = cy0 + i * (r * 2 + padding);
    ctx.beginPath();
    ctx.arc(0, yy, r, 0, Math.PI * 2);
    ctx.fillStyle = color === c ? COLORS.light[c] : COLORS.light.OFF;
    ctx.fill();
    ctx.strokeStyle = COLORS.signalRing;
    ctx.lineWidth = 1;
    ctx.stroke();
    if (color === c) {
      ctx.beginPath();
      ctx.arc(0, yy, r + 2, 0, Math.PI * 2);
      ctx.strokeStyle = withAlpha(COLORS.light[c], 0.35);
      ctx.lineWidth = 2;
      ctx.stroke();
    }
  });
  ctx.restore();
}

function drawLeftSignalHead(
  ctx: CanvasRenderingContext2D,
  approach: Approach,
  color: LeftSignalColor,
): void {
  const pos = signalHeadPosition(approach, 'LEFT');
  const rot = signalHousingRotation(approach);
  const r = 4;
  const padding = 3;
  const hWidth = r * 2 + padding * 2;
  const hHeight = r * 8 + padding * 5;
  ctx.save();
  ctx.translate(pos.x, pos.y);
  ctx.rotate(rot);
  ctx.fillStyle = COLORS.signalHousing;
  roundRect(ctx, -hWidth / 2, -hHeight / 2, hWidth, hHeight, 3);
  ctx.fill();
  const cy0 = -hHeight / 2 + padding + r;
  const colors: LeftSignalColor[] = ['RED', 'YELLOW', 'FLASHING_ORANGE', 'GREEN'];
  colors.forEach((c, i) => {
    const yy = cy0 + i * (r * 2 + padding);
    const lit = color === c;
    ctx.beginPath();
    ctx.arc(0, yy, r, 0, Math.PI * 2);
    ctx.fillStyle = lit ? COLORS.light[c] : COLORS.light.OFF;
    ctx.fill();
    ctx.strokeStyle = COLORS.signalRing;
    ctx.lineWidth = 1;
    ctx.stroke();
    if (lit) {
      ctx.beginPath();
      ctx.arc(0, yy, r + 2, 0, Math.PI * 2);
      ctx.strokeStyle = withAlpha(COLORS.light[c], 0.35);
      ctx.lineWidth = 2;
      ctx.stroke();
    }
  });
  // "L" badge — counter-rotated so it reads upright on screen, positioned
  // just outside the housing on screen (regardless of housing rotation).
  ctx.rotate(-rot);
  const labelOffsetScreen = Math.max(hWidth, hHeight) / 2 + 7;
  ctx.fillStyle = '#7d8896';
  ctx.font = 'bold 9px monospace';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('L', 0, -labelOffsetScreen);
  ctx.restore();
}

input.new_string:
/** Shared horizontal-head renderer. Lights run left-to-right, R first. */
function drawHorizontalSignal(
  ctx: CanvasRenderingContext2D,
  pos: Vec,
  colors: readonly (SignalColor | LeftSignalColor)[],
  active: SignalColor | LeftSignalColor,
  opts: { r: number; padding: number; label?: string },
): void {
  const { r, padding, label } = opts;
  const lightStep = r * 2 + padding;
  const n = colors.length;
  const hWidth = padding * 2 + n * (r * 2) + (n - 1) * padding;
  const hHeight = padding * 2 + r * 2;

  ctx.save();
  ctx.translate(pos.x, pos.y);

  // Housing
  ctx.fillStyle = COLORS.signalHousing;
  roundRect(ctx, -hWidth / 2, -hHeight / 2, hWidth, hHeight, 4);
  ctx.fill();

  // Lights, left to right
  const cx0 = -hWidth / 2 + padding + r;
  colors.forEach((c, i) => {
    const xx = cx0 + i * lightStep;
    const lit = active === c;
    ctx.beginPath();
    ctx.arc(xx, 0, r, 0, Math.PI * 2);
    ctx.fillStyle = lit ? COLORS.light[c] : COLORS.light.OFF;
    ctx.fill();
    ctx.strokeStyle = COLORS.signalRing;
    ctx.lineWidth = 1;
    ctx.stroke();
    if (lit) {
      ctx.beginPath();
      ctx.arc(xx, 0, r + 2, 0, Math.PI * 2);
      ctx.strokeStyle = withAlpha(COLORS.light[c], 0.35);
      ctx.lineWidth = 2;
      ctx.stroke();
    }
  });

  // Optional label above the housing.
  if (label) {
    ctx.fillStyle = '#7d8896';
    ctx.font = 'bold 9px monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(label, 0, -hHeight / 2 - 7);
  }
  ctx.restore();
}

function drawSignalHead(
  ctx: CanvasRenderingContext2D,
  approach: Approach,
  _kind: LaneKind,
  color: SignalColor,
): void {
  const pos = signalHeadPosition(approach, 'STRAIGHT');
  drawHorizontalSignal(ctx, pos, ['RED', 'YELLOW', 'GREEN'] as const, color, { r: 5, padding: 3 });
}

function drawLeftSignalHead(
  ctx: CanvasRenderingContext2D,
  approach: Approach,
  color: LeftSignalColor,
): void {
  const pos = signalHeadPosition(approach, 'LEFT');
  drawHorizontalSignal(
    ctx,
    pos,
    ['RED', 'YELLOW', 'FLASHING_ORANGE', 'GREEN'] as const,
    color,
    { r: 4, padding: 3, label: 'L' },
  );
}

