function drawQueuedCars(ctx: CanvasRenderingContext2D, lanes: Lanes): void {
  for (const a of APPROACHES) {
    for (const k of LANE_KINDS) {
      const movement = `${a}-${k}` as Movement;
      const queue = lanes.queue(movement);
      const rot = carRotation(a);
      const color = carColorFor(a);
      const numSubLanes = subLaneCount(k);
      // Track stack height per sub-lane independently so cars in one lane
      // don't shift when the queue ahead in the *other* lane drains.
      const stackPerSubLane = new Array(numSubLanes).fill(0);
      for (const car of queue) {
        const sub = Math.min(car.subLaneIndex, numSubLanes - 1);
        const stack = stackPerSubLane[sub]++;
        const pos = queuedCarPositionInSubLane(a, k, sub, stack);
        // If we're rendering off-screen, no point continuing for this sub-lane.
        if (pos.x < -CAR_LENGTH || pos.x > CANVAS + CAR_LENGTH ||
