  return {
    throughPos: { x: fxC - HORIZ_OFFSET, y }, // visual left
    leftPos:    { x: fxC + HORIZ_OFFSET, y }, // visual right
    poleAt:     { x: STOP_LINES.W, y: STOP_LINES.S },
  };
}

