  private signalFor(m: Movement, greens: ReadonlySet<Movement>): SignalColor {
    if (greens.has(m)) return 'GREEN';
    if (this.mode === 'YELLOW' && this.currentPhase.movements.has(m)) return 'YELLOW';
    return 'RED';
