/**
 * Walk signals — one per crosswalk, all four show the same state in lockstep
 * (ped phase serves all crosswalks together).
 */
function drawWalkSignals(
  ctx: CanvasRenderingContext2D,
  snap: ControllerSnapshot,
  timeMs: number,
): void {
  const state = snap.walkSignal();
  // Flashing don't-walk blinks at ~2Hz.
  const flashOn = Math.floor(timeMs / 250) % 2 === 0;
  const lit =
    state === 'WALK' ? '#3ad27e' :
    state === 'FLASH_DONT_WALK' ? (flashOn ? '#ff9933' : '#1a1f26') :
    '#ff4d4d';
  const off = '#1a1f26';

  // Position each walk signal on the curb-side of its crosswalk, just outside the road.
  const positions: Array<{ x: number; y: number }> = [
    { x: STOP_LINES.W - 14,    y: CENTER - HALF_ROAD - 14 }, // NW corner walk-button face
    { x: STOP_LINES.E + 14,    y: CENTER - HALF_ROAD - 14 }, // NE
    { x: STOP_LINES.W - 14,    y: CENTER + HALF_ROAD + 14 }, // SW
    { x: STOP_LINES.E + 14,    y: CENTER + HALF_ROAD + 14 }, // SE
  ];
  for (const p of positions) {
    drawWalkIcon(ctx, p.x, p.y, state === 'WALK' || (state === 'FLASH_DONT_WALK' && flashOn), state, lit, off);
  }

  // Small label if a request is pending (waiting to be served).
  if (snap.pedRequestPending() && state === 'DONT_WALK') {
    ctx.save();
    ctx.fillStyle = '#b08800';
    ctx.font = 'bold 10px monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('WALK QUEUED', CENTER, CENTER);
    ctx.restore();
  }
}

function drawWalkIcon(
  ctx: CanvasRenderingContext2D,
  cx: number,
  cy: number,
  isWalkOrFlashing: boolean,
  state: 'WALK' | 'FLASH_DONT_WALK' | 'DONT_WALK',
  lit: string,
  off: string,
): void {
  // Small rounded square housing with a pictogram.
  const sz = 18;
  ctx.save();
  ctx.translate(cx, cy);
  ctx.fillStyle = '#0a0d11';
  roundRect(ctx, -sz / 2, -sz / 2, sz, sz, 3);
  ctx.fill();

  // Pictogram: walking person (when WALK) or upraised hand (when DON'T WALK).
  ctx.fillStyle = isWalkOrFlashing && state !== 'DONT_WALK' ? lit : off;
  ctx.font = 'bold 13px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(state === 'WALK' ? '\u{1F6B6}' : '✋', 0, 1);
  ctx.restore();
}

