describe('Pedestrian phase', () => {
  it('serves a walk request at the next ALL_RED, never preempting green', () => {
    const c = new Controller();
    // Mid-green: press the button.
    c.tick(CONFIG.fixedGreenMs / 2);
    c.requestPed();
    expect(c.snapshot().pedRequestPending()).toBe(true);
    expect(c.snapshot().walkSignal()).toBe('DONT_WALK');
    // Still green — must complete green + yellow + all_red before serving.
    c.tick(1);
    expect(c.snapshot().walkSignal()).toBe('DONT_WALK');
    // Finish green + yellow + all_red. Ped phase starts at next GREEN.
    c.tick(CONFIG.fixedGreenMs / 2 + CONFIG.yellowMs + CONFIG.allRedMs);
    expect(c.snapshot().walkSignal()).toBe('WALK');
    expect(c.snapshot().pedRequestPending()).toBe(false); // request was consumed
  });

  it('PED phase: WALK → FLASH_DONT_WALK → DONT_WALK', () => {
    const c = new Controller();
    c.requestPed();
    // Cycle through current vehicle phase to get to ped.
    c.tick(CONFIG.fixedGreenMs + CONFIG.yellowMs + CONFIG.allRedMs);
    expect(c.snapshot().walkSignal()).toBe('WALK');
    c.tick(CONFIG.pedWalkMs);
    expect(c.snapshot().walkSignal()).toBe('FLASH_DONT_WALK');
    c.tick(CONFIG.pedClearanceMs);
    expect(c.snapshot().walkSignal()).toBe('DONT_WALK');
  });

  it('keeps every vehicle signal RED throughout the entire PED phase', () => {
    const c = new Controller();
    c.requestPed();
    c.tick(CONFIG.fixedGreenMs + CONFIG.yellowMs + CONFIG.allRedMs);
    expect(c.snapshot().walkSignal()).toBe('WALK');
    // Step through the entire ped phase in 100ms increments.
    const totalPed = CONFIG.pedWalkMs + CONFIG.pedClearanceMs + CONFIG.allRedMs;
    for (let t = 0; t < totalPed; t += 100) {
      c.tick(100);
      const snap = c.snapshot();
      // While inPedPhase, no vehicle movement should be green.
      if (snap.walkSignal() !== 'DONT_WALK' || snap.greenMovements().size === 0) {
        // valid: ped phase is showing or transitioning
      }
      // Strict assertion: during the visible ped phases (WALK or FLASH_DONT_WALK),
      // no green movements at all.
      if (snap.walkSignal() !== 'DONT_WALK') {
        expect(snap.greenMovements().size).toBe(0);
      }
    }
  });

  it('multiple presses before service collapse to one (idempotent)', () => {
    const c = new Controller();
    c.requestPed();
    c.requestPed();
    c.requestPed();
    c.tick(CONFIG.fixedGreenMs + CONFIG.yellowMs + CONFIG.allRedMs);
    expect(c.snapshot().walkSignal()).toBe('WALK');
    // After the ped phase, no more pending request.
    c.tick(CONFIG.pedWalkMs + CONFIG.pedClearanceMs + CONFIG.allRedMs);
    expect(c.snapshot().pedRequestPending()).toBe(false);
    expect(c.snapshot().walkSignal()).toBe('DONT_WALK');
  });

  it('walk request is served within bounded time', () => {
    // Worst case: button pressed at start of GREEN. Must serve within
    // maxGreen + yellow + allRed.
    const c = new Controller();
    c.setDemand(() => true); // force green to extend to maxGreen
    c.requestPed();
    const bound = CONFIG.maxGreenMs + CONFIG.yellowMs + CONFIG.allRedMs + 10;
    let served = false;
    for (let t = 0; t < bound; t += 100) {
      c.tick(100);
      if (c.snapshot().walkSignal() === 'WALK') { served = true; break; }
    }
    expect(served).toBe(true);
  });
});

